import{_ as o,o as l,c as s,a5 as e}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"DO类定义","description":"","frontmatter":{"title":"DO类定义","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/DO类定义/DO类定义.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/DO类定义/DO类定义.md"}'),a={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/DO类定义/DO类定义.md"};function r(i,t,n,p,d,g){return l(),s("div",null,[...t[0]||(t[0]=[e('<div><h3 id="一、public-类" tabindex="-1">一、public 类 <a class="header-anchor" href="#一、public-类" aria-label="Permalink to &quot;一、public 类&quot;">​</a></h3><ul><li><strong>定义</strong>：在 Java 中，<code>public</code> 类意味着这个类是公开的，可以被任意其他类访问。</li><li><strong>作用</strong>：<code>public</code> 类通常作为数据模型、服务接口等在整个应用程序中共享和访问的类。</li></ul><h3 id="二、使用以下注解" tabindex="-1">二、使用以下注解 <a class="header-anchor" href="#二、使用以下注解" aria-label="Permalink to &quot;二、使用以下注解&quot;">​</a></h3><p>这些注解通常用在数据模型（特别是实体或 DTO）上，以简化代码编写。</p><ul><li><p><strong>@Data</strong></p></li><li><p><strong>库</strong>：Lombok</p></li><li><p><strong>作用</strong>：自动为类生成所有字段的 getter 方法，为非 final 字段生成 setter 方法，还会生成 <code>toString</code>、<code>equals</code> 和 <code>hashCode</code> 方法。</p></li><li><p><strong>优点</strong>：减少样板代码，使得类更加简洁。</p></li><li><p><strong>@EqualsAndHashCode(callSuper = true)</strong></p></li><li><p><strong>库</strong>：Lombok</p></li><li><p><strong>作用</strong>：生成 <code>equals</code> 和 <code>hashCode</code> 方法的实现，并且通过 <code>callSuper = true</code> 属性指示 Lombok 包含超类（父类）的字段在比较和计算哈希值时。</p></li><li><p><strong>场景</strong>：当你的类继承了其他类，并且你想在比较和哈希计算时包含父类的字段。</p></li><li><p><strong>@ToString(callSuper = true)</strong></p></li><li><p><strong>库</strong>：Lombok</p></li><li><p><strong>作用</strong>：生成 <code>toString</code> 方法的实现，并且通过 <code>callSuper = true</code> 属性指示 Lombok 包含超类（父类）的字段在字符串表示中。</p></li><li><p><strong>场景</strong>：当你需要打印或日志记录类的信息，并且也想包括父类的字段信息。</p></li></ul><h3 id="三、字段中使用以下注解" tabindex="-1">三、字段中使用以下注解 <a class="header-anchor" href="#三、字段中使用以下注解" aria-label="Permalink to &quot;三、字段中使用以下注解&quot;">​</a></h3><p>这些注解通常用在 ORM（对象关系映射）框架中，如 MyBatis-Plus。</p><ul><li><p><strong>@TableId</strong></p></li><li><p><strong>库</strong>：MyBatis-Plus</p></li><li><p><strong>作用</strong>：标记一个字段为数据库表的主键字段。</p></li><li><p><strong>场景</strong>：用在实体类的字段上，用来指示这个字段是对应数据库表的主键列，MyBatis-Plus 会用这个字段作为查询、更新、删除操作的依据。</p></li><li><p><strong>@TableField</strong></p></li><li><p><strong>库</strong>：MyBatis-Plus</p></li><li><p><strong>作用</strong>：将实体类的字段映射到数据库表的列。</p></li><li><p><strong>场景</strong>：当实体类的字段名和数据库表的列名不一致时，可以使用这个注解来指定映射关系。也可以用来指示某些字段不是数据库表的列。</p></li></ul><p>使用这些注解可以大大简化实体类的编写，并且自动处理很多原本需要手动编写的方法，使得代码更加简洁并减少出错的概率。同时，它们也为类与数据库表之间的映射提供了简便的配置方法。</p></div>',1)])])}const _=o(a,[["render",r]]);export{u as __pageData,_ as default};
